java = ['// SPDX-License-Identifier: AGPL-3.0-only',
        'package org.rstudio.studio.client.workbench.views.superrstudio;',
        'import com.google.gwt.i18n.client.Messages;',
        '// Generated from one English/Spanish table; keep both files in step.',
        'public interface LfqMessages extends Messages',
        '{']


def arity(text):
    found = [int(m) for m in re.findall(r'\{(\d+)\}', text)]
    return max(found) + 1 if found else 0


for key, en, es in M:
    n = arity(en)
    params = ', '.join('String p%d' % i for i in range(n))
    escaped = en.replace('\\', '\\\\').replace('"', '\\"')
    # GWT Messages use MessageFormat: single quotes must be doubled
    escaped = escaped.replace("'", "''")
    java.append('   @DefaultMessage("%s") String %s(%s);' % (escaped, key, params))
java.append('}')
open(base + 'LfqMessages.java', 'w', encoding='utf-8', newline='\n').write('\n'.join(java) + '\n')
props = ['# Spanish messages for LfqMessages (generated alongside the Java interface)']
for key, en, es in M:
    props.append('%s=%s' % (key, es.replace("'", "''")))
open(base + 'LfqMessages_es.properties', 'w', encoding='utf-8', newline='\n').write('\n'.join(props) + '\n')
keys = [key for key, en, es in M]
assert len(keys) == len(set(keys)), 'duplicate message keys'
for key, en, es in M:
    assert arity(en) == arity(es), key
print('ok', len(M))
# the Spanish Java implementations used at run time (SuperRStudioLanguage)
import runpy
runpy.run_path(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'spanish_messages.py'))
